    l_inicio   TIMESTAMP; 
    l_fim      TIMESTAMP; 
    l_tempo_ms NUMBER; 

    l_erro     VARCHAR2(1000);
BEGIN 
    l_inicio := SYSTIMESTAMP; 
 
    ADMIN.PRC_OES_VALIDAR_CONSULTA( 
        P_PERGUNTA => :pergunta, 
        P_INTENCAO => :intencao, 
        P_STATUS   => l_status, 
        P_REGRA    => l_regra, 
        P_MOTIVO   => l_motivo 
    ); 
 
    IF l_status <> ''PERMITIDO'' THEN 
 
        INSERT INTO ADMIN.OES_AUDITORIA_DECISAO ( 
            TIPO_EVENTO, 
            INTENCAO, 
            PERGUNTA_USUARIO, 
            STATUS_EXECUCAO, 
            CONTROLE_COBIT, 
            REGRA_OES, 
            MOTIVO_BLOQUEIO 
        ) 
        VALUES ( 
            ''SHOWSQL_BLOQUEADO'', 
            :intencao, 
            :pergunta, 
           ' || ' l_status, 
            ''DSS05'', 
            l_regra, 
            l_motivo 
        ); 
 
        COMMIT; 
 
        HTP.PRN( 
            ''{"status":"'' 
            || REPLACE(l_status, ''"'', ''\"'') 
            || ''","regra":"'' 
            || REPLACE(l_regra, ''"'', ''\"'') 
            || ''","motivo":"'' 
            || REPLACE(l_motivo, ''"'', ''\"'') 
            || ''"}'' 
        ); 
 
        RETURN; 
    END IF; 
 
 
    l_result := DBMS_CLOUD_AI.GENERATE( 
        prompt       => :pergunta, 
        profile_name => ''DATA_FORGE_AI'', 
        action       => ''showsql'' 
    ); 
 
    l_fim := SYSTIMESTAMP; 
 
    l_tempo_ms := 
          EXTRACT(DAY    FROM (l_fim - l_inicio)) * 86400000 
        + EXTRACT(HOUR   FROM (l_fim - l_inicio)) * 3600000 
        + EXTRACT(MINUTE FROM (l_fim - l_inicio)) * 60000 
        + EXTRACT(SECOND FROM (l_fim - l_inicio)) * 1000; 
 
 
    INSERT INTO ADMIN.OES_AUDITORIA_DECISAO ( 
        TIPO_EVENTO, 
        INTENC' || 'AO, 
        PERGUNTA_USUARIO, 
        FONTE_ANALITICA, 
        SQL_GERADO, 
        STATUS_EXECUCAO, 
        CONTROLE_COBIT, 
        REGRA_OES, 
        TEMPO_RESPOSTA_MS 
    ) 
    VALUES ( 
        ''SHOWSQL'', 
        :intencao, 
        :pergunta, 
        ''SELECT_AI_SHOWSQL'', 
        l_result, 
        ''SUCESSO'', 
        ''MEA01'', 
        ''RASTREABILIDADE_SQL'', 
        ROUND(l_tempo_ms) 
    ); 
 
    COMMIT; 
 
 
    LOOP 
        l_chunk := DBMS_LOB.SUBSTR( 
            l_result, 
            8000, 
            l_offset 
        ); 
 
        EXIT WHEN l_chunk IS NULL; 
 
        HTP.PRN(l_chunk); 
 
        l_offset := l_offset + LENGTH(l_chunk); 
    END LOOP; 
 
 
EXCEPTION 
    WHEN OTHERS THEN 

        l_erro := SUBSTR(SQLERRM, 1, 1000);
 
        l_fim := SYSTIMESTAMP; 
 
        l_tempo_ms := 
              EXTRACT(DAY    FROM (l_fim - l_inicio)) * 86400000 
            + EXTRACT(HOUR   FROM (l_fim - l_inicio)) * 36' || '00000 
            + EXTRACT(MINUTE FROM (l_fim - l_inicio)) * 60000 
            + EXTRACT(SECOND FROM (l_fim - l_inicio)) * 1000; 
 
        INSERT INTO ADMIN.OES_AUDITORIA_DECISAO ( 
            TIPO_EVENTO, 
            INTENCAO, 
