            REGRA_OES, 
            TEMPO_RESPOSTA_MS, 
            MOTIVO_BLOQUEIO 
        ) 
        VALUES ( 
            ''ERRO_SHOWSQL'', 
            :intencao, 
            :pergunta, 
            ''ERRO'', 
            ''MEA01'', 
            ''ERRO_EXECUCAO'', 
            ROUND(l_tempo_ms), 
            l_erro
        ); 
 
        COMMIT; 
 
        HTP.PRN( 
            ''{"status":"ERRO","motivo":"'' 
            || REPLACE(l_erro, ''"'', ''\"'') 
            || ''"}'' 
        ); 
END;');

