'SELECT
    NOME_ESTABELECIMENTO,
    MUNICIPIO,
    CNES,
    TIPO_UNIDADE,
    NATUREZA_JURIDICA,
    PORTE,
    LEITOS_SUS,
    UTI_TOTAL_SUS
FROM (
    SELECT
        NOME_ESTABELECIMENTO,
        MUNICIPIO,
        CNES,
        TIPO_UNIDADE,
        NATUREZA_JURIDICA,
        PORTE,
        LEITOS_SUS,
        UTI_TOTAL_SUS,
        ROW_NUMBER() OVER (
            PARTITION BY CNES
            ORDER BY ANO DESC
        ) AS RN
    FROM ADMIN.VW_PERFIL_HOSPITAL
    WHERE UPPER(UF) = UPPER(:uf)
      AND CNES IS NOT NULL
)
WHERE RN = 1
ORDER BY NOME_ESTABELECIMENTO
FETCH FIRST 150 ROWS ONLY');

